def is_balanced(root):
    def check(node):
        if node is None:
            return 0
        left = check(node.left)
        if left == -1:
            return -1
        right = check(node.right)
        if right == -1:
            return -1
        if abs(left - right) > 1:
            return -1
        return max(left, right) + 1

    return check(root) != -1

def get_height(node):
    if node is None:
        return 0
    return max(get_height(node.left), get_height(node.right)) + 1

