def summarize_tree(root):
    if root is None:
        return {'total_nodes': 0, 'leaf_directories': 0, 'max_depth': 0}
    def helper(node, depth):
        if node is None:
            return 0, 0, depth - 1
        total = 1
        left_total, left_leaf, left_depth = helper(node.left, depth + 1)
        right_total, right_leaf, right_depth = helper(node.right, depth + 1)
        total += left_total + right_total
        leaf = 1 if node.left is None and node.right is None else 0
        leaf += left_leaf + right_leaf
        return total, leaf, max(left_depth, right_depth)
    total_nodes, leaf_dirs, max_depth = helper(root, 0)
    return {'total_nodes': total_nodes, 'leaf_directories': leaf_dirs, 'max_depth': max_depth}

root = BinaryTreeNode('/')
root.left = BinaryTreeNode('bin')
root.right = BinaryTreeNode('etc')
print(summarize_tree(root))
